const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2023 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n#container {\n  padding: 6px 12px;\n  border-bottom: 1px solid var(--sys-color-divider);\n}\n\n#contents {\n  margin-top: 14px;\n}\n\n#contents * {\n  background: var(--color-background-elevation-dark-only);\n}\n\n#title {\n  padding-bottom: 12px;\n  font-size: 15px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  border-bottom: 1px solid var(--sys-color-divider);\n  color: var(--color-text-primary);\n  grid-column-start: span 2;\n  font-weight: bold;\n}\n\n#contents .key {\n  grid-column-start: span 2;\n  padding: 12px 0;\n  font-weight: bold;\n  margin-bottom: -1.2em;\n}\n\n#contents .value {\n  grid-column-start: span 2;\n  padding: 12px 0;\n}\n\n#footer {\n  padding-top: 12px;\n  font-size: 15px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  color: var(--color-text-primary);\n  grid-column-start: span 2;\n  font-weight: bold;\n}\n\n#footer .icon-link {\n  vertical-align: sub;\n  float: right;\n}\n\ndevtools-icon-dialog {\n  vertical-align: sub;\n}\n\n/*# sourceURL=preloadingDisabledInfobar.css */\n");export default styles;